### Example Usage with Decorator
```python
from functools import wraps
import os

# Assuming GitError is a custom exception defined elsewhere in your project
class GitError(Exception):
    pass

def check_repo(func):
    """Decorator which checks that we are in a valid git repository."""
    @wraps(func)
    def function_wrapper(*args, **kwargs):
        if not os.path.exists('.git'):
            raise GitError("Not in a valid git repository")
        return func(*args, **kwargs)
    return function_wrapper

@check_repo
def commit_changes():
    """This function will only execute if the current working directory is part of a valid Git repository."""
    print("Changes committed successfully!")

try:
    commit_changes()
except GitError as e:
    print(e)  # Output: Not in a valid git repository
```

